export function detectGroupthink(agentProposals) {
  const uniqueProposals = new Set(agentProposals.map(p => p.title));
  const redundancyScore = (agentProposals.length - uniqueProposals.size) / agentProposals.length;

  return {
    redundancyScore,
    hasGroupthink: redundancyScore > 0.3 // Example threshold for groupthink
  };
}